const response = $input.first().json;
const clusterId = $('Webhook Trigger').first().json.body.cluster_id;
const text = response.content?.[0]?.text || '{}';
let panels;
try { panels = JSON.parse(text); } catch { panels = {}; }

const inputTokens = response.usage?.input_tokens || 0;
const outputTokens = response.usage?.output_tokens || 0;
// Haiku pricing
const costUsd = inputTokens * 0.0000008 + outputTokens * 0.000004;

const verticals = ['web-dev','mobile','data-ml','devops-cloud','design-ux','product','students','entrepreneurs'];
const cacheRows = verticals
  .filter(v => panels[v])
  .map(v => ({
    cluster_id: clusterId,
    cache_key: `vertical:${clusterId}:${v}`,
    cache_type: 'vertical_panel',
    vertical_slug: v,
    content: panels[v],
    model_used: 'haiku',
    input_tokens: Math.round(inputTokens / 8),  // Distribute proportionally
    output_tokens: Math.round(outputTokens / 8),
    cost_usd: costUsd / 8
  }));

return [{ json: { cluster_id: clusterId, panels, cache_rows: cacheRows, cost_usd: costUsd } }];

// Expand cache_rows array into individual items for batch INSERT
const rows = $input.first().json.cache_rows;
return rows.map(row => ({ json: row }));
